import{_ as t,o as i,c as o,ai as a}from"./chunks/framework.BxxKhjs3.js";const s="/pub-blog/assets/image-20260129134551523.CZl_6gn_.png",p="/pub-blog/assets/image-20260129134524149.-X1LuI7w.png",e="/pub-blog/assets/image-20260129134759023.DNKSc-cx.png",r="/pub-blog/assets/image-20260129135155933.Cql7O1hL.png",m="/pub-blog/assets/image-20260129135013524.D30KVyFC.png",g="/pub-blog/assets/image-20260129135100998.DP7k5Kq-.png",l="/pub-blog/assets/image-20260129135556717.tXhVhq_D.png",c="/pub-blog/assets/image-20260129135720762.Bk5SxPQa.png",_="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",f=JSON.parse('{"title":"最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验.md","filePath":"AI人工智能/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验.md","lastUpdated":1769666880000,"__rawMarkdown":"# 最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验\\n\\n> **万少：华为HDE、鸿蒙极客、个人独立开发者**\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 1月27日\\n\\n月之暗面 在1月27日 推出号称**迄今为止最强大的开源模型** 《**Kimi K2.5**》\\n\\n![](assets/image-20260129134551523.png)\\n\\nKimi K2.5 基于 **Kimi K2** 构建，通过约 **15T** 混合视觉和文本 **token** 的持续预训练。\\n\\n\\n\\n作为原生多模态模型，K2.5 提供了最先进的编码和视觉能力，以及自导向的代理群范式。\\n\\n\\n\\n对于复杂任务，**Kimi K2.5 可以自导向一个最多包含 100 个子代理的代理群，执行跨越最多 1,500 个工具调用的并行工作流**。\\n\\n\\n\\n与单代理设置相比，**这可将执行时间缩短高达 4.5 倍**。\\n\\n\\n\\n代理群由 Kimi K2.5 自动创建和编排，无需任何预定义的子代理或工作流。\\n\\n---\\n\\n\\n\\n100多个子代理，这不就是一堆专家围着你转了吗？\\n\\n\\n\\n想象一个场景:\\n\\n\\n\\n你进到了饭店点一盘**鱼香肉丝**：\\n\\n1. **有农业专家帮你选择最好的食材**\\n2. **有营养专家帮你搭配最合适的食材比例**\\n3. **有大厨师帮你烹饪最美味的食物**\\n4. **有艺术家帮你做最精美的摆盘**\\n5. **有音乐家帮你在旁边奏乐**\\n6. 。。。\\n\\n还有很多专家围绕你的需求去服务。\\n\\n![](assets/image-20260129134524149.png)\\n\\n## 能力对比\\n\\nKimi K2.5 可通过 Kimi.com、Kimi App、API 和 Kimi Code 获取。\\n\\nKimi.com & Kimi App 现在支持 4 种模式：K2.5 即时模式、K2.5 思考模式、K2.5 代理模式和 K2.5 代理群（Beta 版）。\\n\\n代理群目前在 Kimi.com 上处于 Beta 测试阶段，高等级付费用户可免费使用。\\n\\n![](assets/image-20260129134759023.png)\\n\\n可以看到和国外顶尖的大模型相比也是毫不逊色。\\n\\n\\n\\n\\n\\n## 如何体验\\n\\n大家如果想要简单体验一下，可以使用腾讯的**CodeBuddy CN**，它已经内置了K2.5模型，可以通过AI编辑器简单感受一下编程的能力。\\n\\n> https://copilot.tencent.com/promotion/?ref=vlt2x31eyhp8a1\\n\\n![](assets/image-20260129135155933.png)\\n\\n如果想要感受 100个代理（牛马）给你服务的感觉，你可以在Kimi官网上去体验一下。\\n\\n> https://www.kimi.com/agent-swarm\\n\\n![](assets/image-20260129135013524.png)\\n\\n目前新业务营业大酬宾 ￥4.99 可以享受7天的使用。\\n\\n![](assets/image-20260129135100998.png)\\n\\n\\n\\n## 一句话生成应用\\n\\n回到**CodeBuddy CN**编辑器内，打开对话框，输入以下提示词：\\n\\n> 帮我做一个单机版本的 HarmonyOS应用单机唯美风格，主题是 时光心情簿。\\n>\\n> 1首屏上是 4个tab，分别是首页-记录-统计-我的 1 首页是一个透明有边框的存钱罐，点击不同的心情图标可以往存钱罐里面存图标，图标下落要有动画效果，存钱罐在瓶子里也有有真实的碰撞效果 \\n>\\n> 2 记录页面是一个可以根据日历来添加心情状态的页面，接受上传最多3章图片 \\n>\\n> 3 统计使用好看的图标技术，可以实现按照年、月、日、不同的心情种类开始统计  \\n>\\n> 4 我的 页面提供常见的一些功能，比如设置风格、字体大小、震动等等 所有页面设计都要有好看的过渡动画，一些页面也可以加入你找到的免费的背景图\\n\\n**CodeBuddy CN**会帮我制定计划，确认无误后，开始干活。\\n\\n![](assets/image-20260129135556717.png)\\n\\n## 最终效果\\n\\n![](assets/image-20260129135720762.png)\\n\\n可以看到，**UI 效果整体还是不错的**，功能是还存在需要仔细调整的部分。\\n\\n但是这个可是生成**HarmonyOS 鸿蒙应用**呀，\\n\\n不是传统的安卓和 iOS，很多AI编辑器做鸿蒙开发还处在语法都不过关的时代！\\n\\n---\\n\\n\\n\\n参考链接：https://www.kimi.com/blog/kimi-k2-5.html\\n\\n\\n\\n## 关注我\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![img](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),K={name:"AI人工智能/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验.md"};function h(b,n,d,u,k,B){return i(),o("div",null,[...n[0]||(n[0]=[a("",47)])])}const q=t(K,[["render",h]]);export{f as __pageData,q as default};
